add_filter( 'woocommerce_cart_item_name', 'perfectpixel_sku_in_cart', 20, 3 );
add_action( 'woocommerce_order_item_meta_start', 'perfectpixel_sku_in_order', 10, 3 );

function perfectpixel_sku_html( $product ) {
	if ( ! $product instanceof WC_Product || '' === (string) $product->get_sku() ) {
		return '';
	}
	return '<div class="perfectpixel-sku" style="font-size:.85em;opacity:.8">' . esc_html( '{{sku_label}}' ) . ' ' . esc_html( $product->get_sku() ) . '</div>';
}

function perfectpixel_sku_in_cart( $name, $cart_item, $cart_item_key ) {
	return $name . perfectpixel_sku_html( $cart_item['data'] ?? null );
}

function perfectpixel_sku_in_order( $item_id, $item, $order ) {
	if ( is_callable( array( $item, 'get_product' ) ) ) {
		echo perfectpixel_sku_html( $item->get_product() ); // phpcs:ignore WordPress.Security.EscapeOutput -- Escaped in the helper.
	}
}
